    "schemaSql": "CREATE TABLE search_ads (ad_id INT PRIMARY KEY, campaign_name VARCHAR(100), headline VARCHAR(100), impressions INT, clicks INT, status VARCHAR(20));\nINSERT INTO search_ads VALUES (1, 'Summer Sale', 'Buy 1 Get 1 Free Shoes', 1500, 0, 'active'), (2, 'Summer Sale', '20% Off All Footwear', 2400, 45, 'active'), (3, 'Fall Promo', 'Designer Coats Under $99', 3100, 0, 'active'), (4, 'Spring Launch', 'New Arrivals Online', 800, 0, 'active'), (5, 'Winter Gear', 'Thermal Socks Sale', 1050, 0, 'paused');",
