    "category": "Aggregations",
    "orderSensitive": true,
    "description": "### Problem Statement\nCoinbase Institutional reports asset yield distributions. Calculate total staking rewards distributed and the total number of rewarded accounts for each cryptocurrency asset.\n\n### Requirements\n- Sum reward_amount rounded to 2 decimal places as total_rewards_paid.\n- Count distinct account_id values as rewarded_accounts.\n- Output columns: asset_symbol, rewarded_accounts, total_rewards_paid.\n- Sort by total_rewards_paid descending, then by asset_symbol ascending.\n\n### Input Schema\n**staking_rewards** (id INT PRIMARY KEY, account_id INT, asset_symbol VARCHAR, reward_amount NUMERIC, payout_date DATE)",
    "schemaSql": "CREATE TABLE staking_rewards (id INT PRIMARY KEY, account_id INT, asset_symbol VARCHAR(10), reward_amount NUMERIC, payout_date DATE);\nINSERT INTO staking_rewards VALUES (1, 101, 'ETH', 1.45, '2025-01-15'), (2, 102, 'ETH', 2.30, '2025-01-15'), (3, 103, 'ETH', 0.85, '2025-01-15'), (4, 101, 'SOL', 14.50, '2025-01-16'), (5, 104, 'SOL', 22.00, '2025-01-16'), (6, 105, 'ADA', 350.00, '2025-01-16'), (7, 102, 'SOL', 8.25, '2025-01-16');",
    "starterSql": "-- 18. Coinbase: Crypto Staking Yield Rewards Summary\n-- Output: asset_symbol, rewarded_accounts, total_rewards_paid\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT asset_symbol, COUNT(DISTINCT account_id) AS rewarded_accounts, ROUND(SUM(reward_amount), 2) AS total_rewards_paid FROM staking_rewards GROUP BY asset_symbol ORDER BY total_rewards_paid DESC, asset_symbol ASC;",
    "expectedColumns": [
      "asset_symbol",
      "rewarded_accounts",
      "total_rewards_paid"
    ],
    "hints": [
      "Group by asset_symbol.",
      "Use COUNT(DISTINCT account_id) to count unique participants.",
      "Sum reward_amount and round to 2 decimals."
    ],
    "explanation": "Financial staking reports combine distinct participant counts with cumulative currency distributions.",
    "number": 18
