    "description": "### Problem Statement\nWalmart Supply Chain Operations triggers replenishment orders when product stock dips. Find all items in the 'Bentonville-1' fulfillment center where current stock is less than or equal to the reorder threshold.\n\n### Requirements\n- Filter for items stored at warehouse 'Bentonville-1'.\n- Include items where current stock is at or below the reorder threshold.\n- Output columns: product_name, current_stock, reorder_threshold.\n- Sort by current_stock ascending, then by product_name ascending.\n\n### Input Schema\n**inventory** (id INT PRIMARY KEY, warehouse_name VARCHAR, product_name VARCHAR, current_stock INT, reorder_threshold INT)",
    "schemaSql": "CREATE TABLE inventory (id INT PRIMARY KEY, warehouse_name VARCHAR(50), product_name VARCHAR(100), current_stock INT, reorder_threshold INT);\nINSERT INTO inventory VALUES (1, 'Bentonville-1', 'Cereal Box', 12, 20), (2, 'Bentonville-1', 'Paper Towels', 50, 25), (3, 'Bentonville-1', 'Detergent Pods', 8, 15), (4, 'Dallas-2', 'Toothpaste', 5, 20), (5, 'Bentonville-1', 'Olive Oil', 0, 10);",
    "starterSql": "-- 21. Walmart: Distribution Warehouse Low Stock Reorder Alert\n-- Output: product_name, current_stock, reorder_threshold\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT product_name, current_stock, reorder_threshold FROM inventory WHERE warehouse_name = 'Bentonville-1' AND current_stock <= reorder_threshold ORDER BY current_stock ASC, product_name ASC;",
