    "schemaSql": "CREATE TABLE shipments (shipment_id INT PRIMARY KEY, product_name VARCHAR(100), weight_lbs NUMERIC, destination_state VARCHAR(10));\nINSERT INTO shipments VALUES (101, 'Sectional Sofa Bed', 145.5, 'TX'), (102, 'Oak Dining Table', 82.0, 'CA'), (103, 'Ceramic Table Lamp', 12.5, 'NY'), (104, 'Armchair Recliner', 75.0, 'FL'), (105, 'Solid Wood Bookshelf', 98.0, 'IL');",
