    "schemaSql": "CREATE TABLE ikea_catalog (article_number VARCHAR(20) PRIMARY KEY, product_name VARCHAR(100), aisle_location VARCHAR(20), is_discontinued BOOLEAN, aisle_stock INT);\nINSERT INTO ikea_catalog VALUES ('001.234.56', 'KALLAX Shelf Unit Blue', 'Aisle 12', TRUE, 4), ('102.345.67', 'BILLY Bookcase Oak', 'Aisle 04', FALSE, 25), ('203.456.78', 'POÄNG Armchair Velvet', 'Aisle 09', TRUE, 2), ('304.567.89', 'LACK Side Table Red', 'Aisle 15', TRUE, 0);",
