    "description": "### Problem Statement\nDHL Express monitors international border clearance efficiency. Calculate the customs pass rate percentage for cross-border shipments by country of origin.\n\n### Requirements\n- Count total shipments per origin_country.\n- Count shipments with clearance_status = 'passed'.\n- Calculate pass_rate as passed shipments divided by total shipments multiplied by 100, rounded to 2 decimal places.\n- Output columns: origin_country, total_shipments, pass_rate.\n- Sort by pass_rate descending, then by origin_country ascending.\n\n### Input Schema\n**customs_shipments** (tracking_number VARCHAR PRIMARY KEY, origin_country VARCHAR, destination_country VARCHAR, clearance_status VARCHAR)",
    "schemaSql": "CREATE TABLE customs_shipments (tracking_number VARCHAR(20) PRIMARY KEY, origin_country VARCHAR(50), destination_country VARCHAR(50), clearance_status VARCHAR(20));\nINSERT INTO customs_shipments VALUES ('DHL-01', 'Germany', 'USA', 'passed'), ('DHL-02', 'Germany', 'USA', 'passed'), ('DHL-03', 'Germany', 'USA', 'inspected'), ('DHL-04', 'Japan', 'USA', 'passed'), ('DHL-05', 'Japan', 'USA', 'passed'), ('DHL-06', 'Brazil', 'USA', 'delayed');",
    "starterSql": "-- 35. DHL: Customs Clearance Pass Rate by Origin Country\n-- Output: origin_country, total_shipments, pass_rate\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT origin_country, COUNT(tracking_number) AS total_shipments, ROUND(SUM(CASE WHEN clearance_status = 'passed' THEN 1 ELSE 0 END) * 100.0 / COUNT(tracking_number), 2) AS pass_rate FROM customs_shipments GROUP BY origin_country ORDER BY pass_rate DESC, origin_country ASC;",
