    "schemaSql": "CREATE TABLE postmates_orders (order_id INT PRIMARY KEY, customer_id INT, delivery_fee NUMERIC, order_time TIMESTAMP);\nINSERT INTO postmates_orders VALUES (101, 1, 6.99, '2025-01-05 23:15:00'), (102, 2, 4.50, '2025-01-05 22:30:00'), (103, 3, 7.50, '2025-01-06 01:45:00'), (104, 4, 3.99, '2025-01-06 18:00:00'), (105, 5, 8.50, '2025-01-06 02:10:00');",
