    "schemaSql": "CREATE TABLE grubhub_orders (id INT PRIMARY KEY, prep_time_bracket VARCHAR(20), status VARCHAR(20));\nINSERT INTO grubhub_orders VALUES (1, '15-30 min', 'completed'), (2, '15-30 min', 'completed'), (3, '15-30 min', 'cancelled'), (4, '30-45 min', 'completed'), (5, '30-45 min', 'cancelled'), (6, '45+ min', 'cancelled'), (7, '45+ min', 'cancelled'), (8, '45+ min', 'completed');",
