    "schemaSql": "CREATE TABLE substitutions (id INT PRIMARY KEY, store_chain VARCHAR(50), customer_accepted BOOLEAN);\nINSERT INTO substitutions VALUES (1, 'Kroger', TRUE), (2, 'Kroger', TRUE), (3, 'Kroger', FALSE), (4, 'HEB', TRUE), (5, 'HEB', TRUE), (6, 'HEB', TRUE), (7, 'Meijer', FALSE), (8, 'Meijer', TRUE);",
