    "schemaSql": "CREATE TABLE enterprise_files (file_id INT PRIMARY KEY, file_name VARCHAR(100), file_size_mb NUMERIC, is_archived BOOLEAN, upload_date DATE);\nINSERT INTO enterprise_files VALUES (1, 'annual_audit_2020.pdf', 14.5, TRUE, '2020-05-12'), (2, 'tax_filing_2021.zip', 450.0, TRUE, '2021-11-20'), (3, 'board_deck_2023.pptx', 35.0, TRUE, '2023-04-10'), (4, 'employee_handbook_2021.pdf', 8.2, FALSE, '2021-08-15'), (5, 'vendor_contracts_2019.tar', 820.0, TRUE, '2019-02-14');",
