    "description": "### Problem Statement\nDropbox User Growth monitors cloud storage quota limits. Calculate the percentage of allocated storage used by each team account, and return accounts that have consumed at least 80% of their quota.\n\n### Requirements\n- Calculate quota_utilization as used_bytes divided by total_quota_bytes multiplied by 100, rounded to 2 decimal places.\n- Filter for accounts with at least 80% quota utilization.\n- Output columns: team_name, quota_utilization.\n- Sort by quota_utilization descending, then by team_name ascending.\n\n### Input Schema\n**dropbox_teams** (team_id INT PRIMARY KEY, team_name VARCHAR, used_bytes BIGINT, total_quota_bytes BIGINT)",
    "schemaSql": "CREATE TABLE dropbox_teams (team_id INT PRIMARY KEY, team_name VARCHAR(50), used_bytes BIGINT, total_quota_bytes BIGINT);\nINSERT INTO dropbox_teams VALUES (1, 'Design Studio', 850000000000, 1000000000000), (2, 'Finance Team', 420000000000, 1000000000000), (3, 'Video Production', 1900000000000, 2000000000000), (4, 'Legal Ops', 790000000000, 1000000000000);",
    "starterSql": "-- 40. Dropbox: Cloud Storage Quota Utilization Percentage\n-- Output: team_name, quota_utilization\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT team_name, ROUND(used_bytes * 100.0 / total_quota_bytes, 2) AS quota_utilization FROM dropbox_teams WHERE (used_bytes * 100.0 / total_quota_bytes) >= 80.00 ORDER BY quota_utilization DESC, team_name ASC;",
