    "description": "### Problem Statement\nCanva Asset Rendering team manages export GPU queues. Calculate the total number of design exports requested for each output file format.\n\n### Requirements\n- Group exports by file_format.\n- Count total export requests per format.\n- Output columns: file_format, export_count.\n- Sort by export_count descending, then by file_format ascending.\n\n### Input Schema\n**design_exports** (export_id INT PRIMARY KEY, user_id INT, design_title VARCHAR, file_format VARCHAR)",
    "schemaSql": "CREATE TABLE design_exports (export_id INT PRIMARY KEY, user_id INT, design_title VARCHAR(100), file_format VARCHAR(10));\nINSERT INTO design_exports VALUES (1, 10, 'Instagram Story Promo', 'PNG'), (2, 11, 'Print Poster A4', 'PDF'), (3, 12, 'YouTube Banner', 'PNG'), (4, 13, 'Animated Intro', 'MP4'), (5, 14, 'Company Flyer', 'PDF'), (6, 15, 'Presentation Slide', 'PDF'), (7, 16, 'Logo Vector', 'SVG');",
    "starterSql": "-- 43. Canva: Exported Graphic Design Format Distribution\n-- Output: file_format, export_count\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT file_format, COUNT(export_id) AS export_count FROM design_exports GROUP BY file_format ORDER BY export_count DESC, file_format ASC;",
