    "schemaSql": "CREATE TABLE shops (id INT PRIMARY KEY, shop_name VARCHAR(100), owner_name VARCHAR(50));\nCREATE TABLE shop_orders (order_id INT PRIMARY KEY, shop_id INT, order_amount NUMERIC);\nINSERT INTO shops VALUES (1, 'Clay & Kiln Pottery', 'Mia Ramos'), (2, 'Knitted Warmth', 'Chloe Bennett'), (3, 'Woodland Woodworks', 'Sam Vance');\nINSERT INTO shop_orders VALUES (101, 1, 85.00), (102, 1, 42.50), (103, 3, 150.00);",
