    "schemaSql": "CREATE TABLE repositories (id INT PRIMARY KEY, repo_name VARCHAR(100), open_prs INT, open_issues INT);\nINSERT INTO repositories VALUES (1, 'react-ui-kit', 45, 20), (2, 'rust-parser', 12, 15), (3, 'py-data-tools', 28, 5), (4, 'node-logger', 8, 8), (5, 'ml-vision-core', 50, 42);",
