    "category": "Joins & Set Theory",
    "orderSensitive": true,
    "description": "### Problem Statement\nPatreon Creator Success identifies new creators struggling to gain initial patrons. Find all registered creator pages that have zero active monthly patrons.\n\n### Requirements\n- Join creators and patrons using a LEFT JOIN.\n- Filter for creators with no patron records.\n- Output columns: creator_id, page_title, category.\n- Sort by page_title ascending.\n\n### Input Schema\n**patreon_creators** (id INT PRIMARY KEY, page_title VARCHAR, category VARCHAR)\n\n**patrons** (id INT PRIMARY KEY, creator_id INT, monthly_pledge NUMERIC)",
    "schemaSql": "CREATE TABLE patreon_creators (id INT PRIMARY KEY, page_title VARCHAR(100), category VARCHAR(50));\nCREATE TABLE patrons (id INT PRIMARY KEY, creator_id INT, monthly_pledge NUMERIC);\nINSERT INTO patreon_creators VALUES (1, 'Indie Game Dev Log', 'Gaming'), (2, 'Weekly Philosophy Podcast', 'Podcasts'), (3, 'Watercolor Painting Studio', 'Art');\nINSERT INTO patrons VALUES (101, 1, 10.00), (102, 1, 25.00), (103, 3, 5.00);",
    "starterSql": "-- 55. Patreon: Patreon Creators with Zero Active Monthly Patrons\n-- Output: creator_id, page_title, category\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT c.id AS creator_id, c.page_title, c.category FROM patreon_creators c LEFT JOIN patrons p ON c.id = p.creator_id WHERE p.id IS NULL ORDER BY c.page_title ASC;",
    "expectedColumns": [
      "creator_id",
      "page_title",
      "category"
    ],
    "hints": [
      "LEFT JOIN patrons on creator_id.",
      "Check WHERE p.id IS NULL.",
      "Order by page_title ASC."
    ],
    "explanation": "Zero-patron queries trigger automatic creator education emails on promotion strategies.",
    "number": 55
