    "schemaSql": "CREATE TABLE digital_wallets (wallet_id INT PRIMARY KEY, user_email VARCHAR(100), balance NUMERIC, last_login_date DATE);\nINSERT INTO digital_wallets VALUES (1, 'dan@olddomain.com', 142.50, '2023-08-14'), (2, 'sarah@active.com', 450.00, '2025-01-02'), (3, 'tom@dormant.org', 25.00, '2022-12-10'), (4, 'anna@empty.net', 0.00, '2023-05-20'), (5, 'chris@forgotten.com', 890.10, '2023-11-28');",
