    "orderSensitive": true,
    "description": "### Problem Statement\nSquare Register Merchant Portal calculates end-of-day register settlements. Compute the total daily sales volume and total transaction count for each terminal.\n\n### Requirements\n- Group transactions by terminal_id and sales_date.\n- Calculate total sales volume rounded to 2 decimal places as total_sales.\n- Count transactions as total_transactions.\n- Output columns: terminal_id, sales_date, total_transactions, total_sales.\n- Sort by sales_date ascending, then by terminal_id ascending.\n\n### Input Schema\n**pos_transactions** (id INT PRIMARY KEY, terminal_id VARCHAR, sales_date DATE, amount NUMERIC)",
    "schemaSql": "CREATE TABLE pos_transactions (id INT PRIMARY KEY, terminal_id VARCHAR(20), sales_date DATE, amount NUMERIC);\nINSERT INTO pos_transactions VALUES (1, 'TERM-01', '2025-01-10', 25.50), (2, 'TERM-01', '2025-01-10', 42.00), (3, 'TERM-02', '2025-01-10', 115.00), (4, 'TERM-01', '2025-01-11', 80.25), (5, 'TERM-02', '2025-01-11', 54.00);",
    "starterSql": "-- 58. Square: Daily Sales Transaction Totals per POS Terminal\n-- Output: terminal_id, sales_date, total_transactions, total_sales\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT terminal_id, sales_date, COUNT(id) AS total_transactions, ROUND(SUM(amount), 2) AS total_sales FROM pos_transactions GROUP BY terminal_id, sales_date ORDER BY sales_date ASC, terminal_id ASC;",
