    "schemaSql": "CREATE TABLE twitch_streams (id INT PRIMARY KEY, category_name VARCHAR(50), hours_watched INT);\nINSERT INTO twitch_streams VALUES (1, 'Valorant', 35000), (2, 'Valorant', 25000), (3, 'Just Chatting', 45000), (4, 'Just Chatting', 15000), (5, 'League of Legends', 60000), (6, 'Chess', 8000);",
    "starterSql": "-- 61. Twitch: Twitch Categories with Over 50,000 Total Watch Hours\n-- Output: category_name, total_hours\nSELECT\n  -- Your code here\n;",
