    "schemaSql": "CREATE TABLE pin_saves (id INT PRIMARY KEY, pin_title VARCHAR(100), board_id INT);\nINSERT INTO pin_saves VALUES (1, 'Minimalist Kitchen Remodel', 101), (2, 'Minimalist Kitchen Remodel', 102), (3, 'Minimalist Kitchen Remodel', 103), (4, 'Easy Sourdough Bread', 201), (5, 'Easy Sourdough Bread', 202), (6, 'Autumn Capsule Wardrobe', 301), (7, 'Autumn Capsule Wardrobe', 302), (8, 'Autumn Capsule Wardrobe', 303), (9, 'Autumn Capsule Wardrobe', 304);",
    "starterSql": "-- 62. Pinterest: Pinterest Pins Saved Across Multiple User Boards\n-- Output: pin_title, distinct_boards\nSELECT\n  -- Your code here\n;",
