    "orderSensitive": true,
    "description": "### Problem Statement\nYelp Elite Squad highlights local dining gems. Find all business establishments that have received at least 3 customer reviews and maintain an average rating of 4.5 or higher.\n\n### Requirements\n- Calculate average stars rounded to 2 decimal places as avg_rating.\n- Count total reviews as review_count.\n- Filter for review_count >= 3 and avg_rating >= 4.50 using HAVING.\n- Output columns: business_name, review_count, avg_rating.\n- Sort by avg_rating descending, then by review_count descending.\n\n### Input Schema\n**yelp_reviews** (id INT PRIMARY KEY, business_name VARCHAR, stars NUMERIC)",
    "schemaSql": "CREATE TABLE yelp_reviews (id INT PRIMARY KEY, business_name VARCHAR(100), stars NUMERIC);\nINSERT INTO yelp_reviews VALUES (1, 'Artisan Sourdough Bakery', 5.0), (2, 'Artisan Sourdough Bakery', 4.5), (3, 'Artisan Sourdough Bakery', 4.8), (4, 'Golden Wok Express', 4.0), (5, 'Golden Wok Express', 4.5), (6, 'Golden Wok Express', 4.2), (7, 'Little Italy Trattoria', 5.0), (8, 'Little Italy Trattoria', 4.8), (9, 'Little Italy Trattoria', 4.9);",
    "starterSql": "-- 63. Yelp: Small Businesses with High Ratings and Review Volume\n-- Output: business_name, review_count, avg_rating\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT business_name, COUNT(id) AS review_count, ROUND(AVG(stars), 2) AS avg_rating FROM yelp_reviews GROUP BY business_name HAVING COUNT(id) >= 3 AND AVG(stars) >= 4.50 ORDER BY avg_rating DESC, review_count DESC;",
