    "schemaSql": "CREATE TABLE reservations (id INT PRIMARY KEY, restaurant_name VARCHAR(100), status VARCHAR(20));\nINSERT INTO reservations VALUES (1, 'Chez Panisse', 'seated'), (2, 'Chez Panisse', 'cancelled'), (3, 'Chez Panisse', 'cancelled'), (4, 'Osteria Mozza', 'seated'), (5, 'Osteria Mozza', 'cancelled'), (6, 'Le Bernardin', 'cancelled'), (7, 'Le Bernardin', 'cancelled'), (8, 'Le Bernardin', 'cancelled');",
