    "description": "### Problem Statement\nKickstarter Discover highlights fully funded projects. Find all crowdfunding campaigns where pledged funds equaled or surpassed the stated goal.\n\n### Requirements\n- Calculate funding_pct as pledged_amount divided by goal_amount multiplied by 100, rounded to 2 decimal places.\n- Filter for campaigns where pledged_amount >= goal_amount.\n- Output columns: project_title, goal_amount, pledged_amount, funding_pct.\n- Sort by funding_pct descending, then by project_title ascending.\n\n### Input Schema\n**campaigns** (id INT PRIMARY KEY, project_title VARCHAR, goal_amount NUMERIC, pledged_amount NUMERIC)",
    "schemaSql": "CREATE TABLE campaigns (id INT PRIMARY KEY, project_title VARCHAR(100), goal_amount NUMERIC, pledged_amount NUMERIC);\nINSERT INTO campaigns VALUES (1, 'Smart Ceramic Mug', 15000, 24500), (2, 'Tabletop RPG Dice Set', 5000, 8500), (3, 'Eco Backpack', 20000, 18000), (4, 'Minimalist Mechanical Keyboard', 12000, 12000);",
    "starterSql": "-- 67. Kickstarter: Crowdfunding Campaigns Achieving Over 100% of Goal\n-- Output: project_title, goal_amount, pledged_amount, funding_pct\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT project_title, goal_amount, pledged_amount, ROUND(pledged_amount * 100.0 / goal_amount, 2) AS funding_pct FROM campaigns WHERE pledged_amount >= goal_amount ORDER BY funding_pct DESC, project_title ASC;",
