    "description": "### Problem Statement\nGoFundMe Community Engagement promotes active grassroots causes. Find all charitable campaigns that have received contributions from at least 3 distinct donors.\n\n### Requirements\n- Group donations by campaign_title.\n- Count distinct donor_id values.\n- Filter for campaigns with distinct donors >= 3 using HAVING.\n- Output columns: campaign_title, donor_count.\n- Sort by donor_count descending, then by campaign_title ascending.\n\n### Input Schema\n**donations** (id INT PRIMARY KEY, campaign_title VARCHAR, donor_id INT, amount NUMERIC)",
    "schemaSql": "CREATE TABLE donations (id INT PRIMARY KEY, campaign_title VARCHAR(100), donor_id INT, amount NUMERIC);\nINSERT INTO donations VALUES (1, 'Community Animal Shelter Renovation', 10, 50.00), (2, 'Community Animal Shelter Renovation', 11, 25.00), (3, 'Community Animal Shelter Renovation', 12, 100.00), (4, 'Local Youth Robotics Team', 20, 200.00), (5, 'Local Youth Robotics Team', 21, 50.00), (6, 'Neighborhood Tree Planting', 30, 20.00);",
    "starterSql": "-- 68. GoFundMe: Fundraisers with High Donor Backer Counts\n-- Output: campaign_title, donor_count\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT campaign_title, COUNT(DISTINCT donor_id) AS donor_count FROM donations GROUP BY campaign_title HAVING COUNT(DISTINCT donor_id) >= 3 ORDER BY donor_count DESC, campaign_title ASC;",
