    "schemaSql": "CREATE TABLE authors (id INT PRIMARY KEY, name VARCHAR(50));\nCREATE TABLE articles (id INT PRIMARY KEY, author_id INT, title VARCHAR(100), published_date DATE);\nINSERT INTO authors VALUES (1, 'Cassie Kozyrkov'), (2, 'Will Larson'), (3, 'Gergely Orosz');\nINSERT INTO articles VALUES (101, 1, 'Data Science Decision Intelligence', '2024-02-14'), (102, 1, 'AI Statistics Essentials', '2024-05-18'), (103, 2, 'An Elegant Puzzle Excerpt', '2024-03-01'), (104, 3, 'The Pragmatic Engineer Issue #1', '2024-01-10'), (105, 3, 'Tech Layoffs Analysis', '2024-04-22'), (106, 3, 'Staff Plus Archetypes', '2024-07-15');",
    "starterSql": "-- 69. Medium: Publication Writers with Multiple Articles in 2024\n-- Output: author_name, articles_published\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT a.name AS author_name, COUNT(ar.id) AS articles_published FROM authors a JOIN articles ar ON a.id = ar.author_id WHERE ar.published_date BETWEEN '2024-01-01' AND '2024-12-31' GROUP BY a.id, a.name HAVING COUNT(ar.id) >= 2 ORDER BY articles_published DESC, author_name ASC;",
