    "schemaSql": "CREATE TABLE goodreads_books (id INT PRIMARY KEY, author_name VARCHAR(100), title VARCHAR(100), average_rating NUMERIC);\nINSERT INTO goodreads_books VALUES (1, 'Brandon Sanderson', 'The Way of Kings', 4.65), (2, 'Brandon Sanderson', 'Mistborn', 4.45), (3, 'Ted Chiang', 'Stories of Your Life', 4.35), (4, 'Ted Chiang', 'Exhalation', 4.25), (5, 'Random Novelist', 'Debut Mystery', 3.40);",
