    "description": "### Problem Statement\nAmazon Global Fulfillment is preparing a cross-regional inventory audit. Consolidate inventory listings from the North American warehouse and European distribution centers into an unified multi-region stock overview.\n\n### Requirements\n- Append all inventory records from the US catalog and EU catalog into a unified list.\n- Tag US items with a region value of 'US' and European items with 'EU'.\n- Only include items with positive on-hand inventory.\n- Output columns: sku, product_name, stock_qty, region.\n- Sort by sku ascending, then by region ascending.\n\n### Input Schema\n**us_catalog** (sku VARCHAR, product_name VARCHAR, stock_qty INT)\n\n**eu_catalog** (sku VARCHAR, product_name VARCHAR, stock_qty INT)",
    "schemaSql": "CREATE TABLE us_catalog (sku VARCHAR(20) PRIMARY KEY, product_name VARCHAR(100), stock_qty INT);\nCREATE TABLE eu_catalog (sku VARCHAR(20) PRIMARY KEY, product_name VARCHAR(100), stock_qty INT);\nINSERT INTO us_catalog VALUES ('ELEC-1001', 'Kindle Oasis', 42), ('ELEC-1002', 'Fire TV Stick', 150), ('BOOK-2001', 'SQL Guide', 0), ('HOME-3001', 'Smart Plug', 85);\nINSERT INTO eu_catalog VALUES ('ELEC-1001', 'Kindle Oasis', 28), ('ELEC-1003', 'Echo Dot EU', 95), ('HOME-3001', 'Smart Plug', 0), ('BEAUTY-401', 'Face Cream', 60);",
    "starterSql": "-- 73. Amazon: Merging US and European Fulfillment Center Catalogs\n-- Output: sku, product_name, stock_qty, region\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT sku, product_name, stock_qty, 'US' AS region FROM us_catalog WHERE stock_qty > 0 UNION ALL SELECT sku, product_name, stock_qty, 'EU' AS region FROM eu_catalog WHERE stock_qty > 0 ORDER BY sku ASC, region ASC;",
