    "description": "### Problem Statement\nMeta Ads Analytics logs mobile user taps and desktop browser clicks in separate data pipelines. Create an aggregated chronological log of all ad click events for campaign 4001 across both platforms.\n\n### Requirements\n- Extract all ad click logs for campaign ID 4001 from both mobile and desktop tracking tables.\n- Label the traffic source as 'mobile' or 'desktop' accordingly.\n- Keep every click event without deduplicating identical timestamps.\n- Output columns: click_id, user_id, platform, event_time.\n- Sort by event_time ascending, then by click_id ascending.\n\n### Input Schema\n**mobile_clicks** (click_id INT, campaign_id INT, user_id INT, event_time TIMESTAMP)\n\n**desktop_clicks** (click_id INT, campaign_id INT, user_id INT, event_time TIMESTAMP)",
    "schemaSql": "CREATE TABLE mobile_clicks (click_id INT PRIMARY KEY, campaign_id INT, user_id INT, event_time TIMESTAMP);\nCREATE TABLE desktop_clicks (click_id INT PRIMARY KEY, campaign_id INT, user_id INT, event_time TIMESTAMP);\nINSERT INTO mobile_clicks VALUES (1001, 4001, 10, '2025-02-01 09:15:00'), (1002, 4001, 12, '2025-02-01 09:30:00'), (1003, 4002, 15, '2025-02-01 10:00:00');\nINSERT INTO desktop_clicks VALUES (2001, 4001, 11, '2025-02-01 09:20:00'), (2002, 4001, 14, '2025-02-01 09:45:00'), (2003, 4003, 16, '2025-02-01 11:15:00');",
    "starterSql": "-- 75. Meta: Combining Mobile and Desktop Ad Interaction Logs\n-- Output: click_id, user_id, platform, event_time\nSELECT\n  -- Your code here\n;",
