    "description": "### Problem Statement\nDoorDash Merchant Reliability is rewarding perfect order fulfillment. Identify all partner restaurants that have fulfilled customer orders but have never had any order cancelled.\n\n### Requirements\n- Find restaurants that appear in the order log.\n- Ensure the restaurant has never experienced an order with a 'cancelled' status.\n- Use a subquery to exclude restaurants with cancelled orders.\n- Output columns: restaurant_name, city.\n- Sort alphabetically by restaurant_name ascending.\n\n### Input Schema\n**partner_merchants** (id INT, restaurant_name VARCHAR, city VARCHAR)\n\n**food_orders** (id INT, restaurant_id INT, status VARCHAR)",
    "schemaSql": "CREATE TABLE partner_merchants (id INT PRIMARY KEY, restaurant_name VARCHAR(100), city VARCHAR(50));\nCREATE TABLE food_orders (id INT PRIMARY KEY, restaurant_id INT, status VARCHAR(20));\nINSERT INTO partner_merchants VALUES (1, 'Pho Delight', 'Seattle'), (2, 'Baja Cantina', 'Austin'), (3, 'Tokyo Ramen', 'San Francisco'), (4, 'Napoli Pizza', 'Chicago'), (5, 'Fresh Salads', 'Denver');\nINSERT INTO food_orders VALUES (101, 1, 'completed'), (102, 1, 'completed'), (103, 2, 'completed'), (104, 2, 'cancelled'), (105, 3, 'completed'), (106, 4, 'cancelled');",
    "starterSql": "-- 87. DoorDash: Active Restaurants That Have Never Received a Cancellation\n-- Output: restaurant_name, city\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT restaurant_name, city FROM partner_merchants WHERE id IN (SELECT restaurant_id FROM food_orders) AND id NOT IN (SELECT restaurant_id FROM food_orders WHERE status = 'cancelled') ORDER BY restaurant_name ASC;",
