    "description": "### Problem Statement\nApple App Store Review is compiling an audit of enterprise mobile developers. Identify all software developers who offer at least one application with a price exceeding $50.00.\n\n### Requirements\n- Identify developers whose developer ID is associated with an app priced above $50.00.\n- Execute the lookup using an IN subquery against the store apps table.\n- Output columns: developer_name, country.\n- Sort alphabetically by developer_name ascending.\n\n### Input Schema\n**developers** (id INT, developer_name VARCHAR, country VARCHAR)\n\n**store_apps** (id INT, developer_id INT, app_name VARCHAR, price NUMERIC)",
    "schemaSql": "CREATE TABLE developers (id INT PRIMARY KEY, developer_name VARCHAR(100), country VARCHAR(50));\nCREATE TABLE store_apps (id INT PRIMARY KEY, developer_id INT, app_name VARCHAR(100), price NUMERIC);\nINSERT INTO developers VALUES (1, 'OmniCorp Tech', 'USA'), (2, 'Nordic Indie Studio', 'Sweden'), (3, 'Pro CAD Solutions', 'Germany'), (4, 'Casual Games Lab', 'USA');\nINSERT INTO store_apps VALUES (101, 1, 'Cloud Sync Pro', 14.99), (102, 1, 'Enterprise Security Suite', 79.99), (103, 2, 'Pixel Runner', 2.99), (104, 3, '3D Architectural CAD', 129.99), (105, 4, 'Bubble Pop', 0.00);",
    "starterSql": "-- 88. Apple: Developers Publishing Premium Apps Priced Above $50\n-- Output: developer_name, country\nSELECT\n  -- Your code here\n;",
