    "description": "### Problem Statement\nGoogle Ads Finance is reviewing enterprise ad accounts. Identify all active ad campaigns whose allocated monthly budget exceeds the platform-wide average monthly budget across all active campaigns.\n\n### Requirements\n- Filter for active campaigns only (status of 'active').\n- Select campaigns whose monthly budget is greater than the average monthly budget of all active campaigns.\n- Use a scalar subquery to calculate the average budget threshold.\n- Output columns: campaign_name, client_name, monthly_budget.\n- Sort by monthly_budget descending, then by campaign_name ascending.\n\n### Input Schema\n**ad_campaigns** (id INT, campaign_name VARCHAR, client_name VARCHAR, monthly_budget NUMERIC, status VARCHAR)",
    "schemaSql": "CREATE TABLE ad_campaigns (id INT PRIMARY KEY, campaign_name VARCHAR(100), client_name VARCHAR(100), monthly_budget NUMERIC, status VARCHAR(20));\nINSERT INTO ad_campaigns VALUES (1, 'Summer Flash Sale', 'Nike', 75000.00, 'active'), (2, 'Back to School Promo', 'Target', 45000.00, 'active'), (3, 'Holiday Preview', 'Best Buy', 120000.00, 'active'), (4, 'Brand Awareness', 'Local Bakery', 8000.00, 'active'), (5, 'Legacy Spring Ad', 'Old Navy', 90000.00, 'paused');",
    "starterSql": "-- 90. Google: High-Spend Advertising Campaigns Exceeding Division Average Budget\n-- Output: campaign_name, client_name, monthly_budget\nSELECT\n  -- Your code here\n;",
    "referenceSql": "SELECT campaign_name, client_name, monthly_budget FROM ad_campaigns WHERE status = 'active' AND monthly_budget > (SELECT AVG(monthly_budget) FROM ad_campaigns WHERE status = 'active') ORDER BY monthly_budget DESC, campaign_name ASC;",
